function evalRPN(tokens: string[]): number {
  // Стек операндов: числа и уже вычисленные подвыражения
  const stack: number[] = [];

  for (const token of tokens) {
    if (token === '+' || token === '-' || token === '*' || token === '/') {
      // Оператор применяется к двум последним операндам.
      // Порядок важен: сначала снимаем ПРАВЫЙ операнд, затем левый
      const b = stack.pop()!;
      const a = stack.pop()!;
      let result: number;
      switch (token) {
        case '+':
          result = a + b;
          break;
        case '-':
          result = a - b;
          break;
        case '*':
          result = a * b;
          break;
        default:
          // Деление с округлением к нулю (Math.floor для отрицательных дал бы не то)
          result = Math.trunc(a / b);
      }
      // Результат подвыражения — снова операнд
      stack.push(result);
    } else {
      // Число (в том числе отрицательное, например "-11")
      stack.push(Number(token));
    }
  }

  // В корректном выражении в стеке остаётся ровно одно значение
  return stack[0];
}

// Время: O(n) — каждый токен обрабатывается один раз
// Память: O(n) — стек операндов
